import React, { useState, useEffect } from 'react';
import { Play, ArrowUpRight, Camera } from 'lucide-react';
import { ASSET_BASE_URL, HIDDEN_PORTFOLIO_IDS } from '../config';
import { PORTFOLIO_PROJECTS } from '../data/portfolioData';
import { Language, PortfolioProject, MediaAsset } from '../types';
import { AutoPlayVideo } from '../components/AutoPlayVideo';
import { LivePhotoCard } from '../components/LivePhotoCard';
import { ChapterFilter } from '../components/Navbar';

interface PortfolioViewProps {
  language: Language;
  onNavigate: (view: string, projectId?: string) => void;
  onOpenLightbox: (asset: MediaAsset, projectGallery: MediaAsset[]) => void;
  onOpenVideo: (project: PortfolioProject) => void;
  activeChapter?: ChapterFilter;
  onSelectChapter?: (chapter: ChapterFilter) => void;
}

function getPhotographyCategoryBadge(project: PortfolioProject, language: Language): string {
  if (project.id === 'event-ceremony' || project.id.includes('raoul')) {
    return language === 'en'
      ? 'OFFICIAL CEREMONY & REPORTAGE'
      : 'OFFICIELL CEREMONI & REPORTAGE';
  }
  if (
    project.id.includes('fashion') ||
    project.id.includes('gullbo') ||
    project.id.includes('maddwoo') ||
    project.id.includes('seams') ||
    project.id.includes('sthlm-misc') ||
    project.id.includes('rasmus') ||
    project.id.includes('jennifer-blom')
  ) {
    return language === 'en'
      ? 'FASHION & MODELING'
      : 'MODE & MODELLFOTOGRAFI';
  }
  if (project.id.includes('sofia-perlgard') || project.id.includes('vesta-rone')) {
    return language === 'en'
      ? 'STUDIO & MODELING PORTRAITURE'
      : 'STUDIO- & MODELLPORTRÄTT';
  }
  if (project.sector === 'culture_performance') {
    return language === 'en'
      ? 'CONCERTS & STAGE'
      : 'KONSERT & SCEN';
  }
  if (project.sector === 'corporate_events') {
    return language === 'en'
      ? 'OFFICIAL EVENT & REPORTAGE'
      : 'OFFICIELLT EVENT & REPORTAGE';
  }
  return language === 'en'
    ? 'PHOTOGRAPHY & EDITORIAL'
    : 'FOTOGRAFI & EDITORIAL';
}

